interface LocaleContextValue { locale: Locale; setLocale: (locale: Locale) => void; t: (english: string) => string; languageName: string }
const LocaleContext = createContext<LocaleContextValue | null>(null);
const storageKey = "ebusinessrw-locale";

function detectLocale(): Locale {
  try {
    const saved = localStorage.getItem(storageKey);
    if (saved === "en" || saved === "rw" || saved === "fr") return saved;
  } catch { /* Storage can be unavailable in private browsing. */ }
  const browserLanguage = navigator.language.toLowerCase();
  if (browserLanguage.startsWith("rw")) return "rw";
  if (browserLanguage.startsWith("fr")) return "fr";
  return "en";
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(detectLocale);
  const setLocale = (next: Locale) => {
    setLocaleState(next);
    try { localStorage.setItem(storageKey, next); } catch { /* The selection still applies for this session. */ }
  };
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const value = useMemo<LocaleContextValue>(() => ({ locale, setLocale, languageName: localeNames[locale], t: (english) => locale === "en" ? english : dashboardControlsCopy[locale][english] ?? paymentAdminCopy[locale][english] ?? billingCopy[locale][english] ?? dashboardExtraCopy[locale][english] ?? dashboardCopy[locale][english] ?? authCopy[locale][english] ?? componentCopy[locale][english] ?? onboardingCopy[locale][english] ?? screensCopy[locale][english] ?? operationsCopy[locale][english] ?? appCopy[locale][english] ?? workflowCopy[locale][english] ?? pricingCopy[locale][english] ?? landingCopy[locale][english] ?? extendedCopy[locale][english] ?? copy[locale][english] ?? english }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error("useLanguage must be used inside LanguageProvider");
  return context;
}

export function LanguageSwitcher({ compact = false }: { compact?: boolean }) {
  const { locale, setLocale, t } = useLanguage();
  return <label className={`inline-flex items-center gap-2 rounded-xl border border-current/15 bg-white/70 px-3 ${compact ? "min-h-9" : "min-h-10"}`}>
    <Globe2 size={15} aria-hidden="true" />
    <span className="sr-only">{t("Choose language")}</span>
    <select aria-label={t("Choose language")} value={locale} onChange={(event) => setLocale(event.target.value as Locale)} className="max-w-[7.5rem] cursor-pointer bg-transparent text-xs font-semibold outline-none">
      <option value="en">English</option><option value="rw">Ikinyarwanda</option><option value="fr">Français</option>
    </select>
  </label>;
}

